// Get the data from the HTTP Request node
const data = $input.first().json;

// Function to calculate average change percentage
const getAverageChange = (array) => {
  if (!array || array.length === 0) return 0;
  const sum = array.slice(0, 10).reduce((acc, stock) => {
    // Remove the '%' sign and convert to a number
    return acc + parseFloat(stock.change_percentage.replace('%', ''));
  }, 0);
  return (sum / Math.min(array.length, 10)).toFixed(2);
};

// Calculate metrics
const avgGainerMove = getAverageChange(data.top_gainers);
const avgLoserMove = getAverageChange(data.top_losers);
const marketSentiment = avgGainerMove > Math.abs(avgLoserMove) ? "Bullish" : "Bearish";

// Return the enhanced data
return {
  market_summary: {
    sentiment: marketSentiment,
    average_gainer_percent: avgGainerMove + "%",
    average_loser_percent: avgLoserMove + "%",
    top_performer: data.top_gainers[0].ticker,
    worst_performer: data.top_losers[0].ticker,
    timestamp: data.last_updated
  },
  // Keep the original data just in case the AI needs it
  raw_gainers: data.top_gainers.slice(0, 5), 
  raw_losers: data.top_losers.slice(0, 5)
};

// Get the ticker from the market summary
let ticker = $input.first().json.market_summary.top_performer;

// Remove any special characters (like ^) so the News API doesn't crash
let cleanTicker = ticker.replace(/[^a-zA-Z0-9]/g, "");

// Return the cleaned ticker back to the flow
return {
  market_summary: $input.first().json.market_summary,
  clean_ticker: cleanTicker
};
